$Politics_12 = '12.0 INFORMAÇÕES PROPRIETÁRIAS E SEGREDOS COMERCIAIS';
$Politics_12_text = '';

    //-------------------------//

$Politics_12_01 = '12.1 Relatórios Comerciais, Listas e Informações Proprietárias';
$Politics_12_01_text = 'Ao aceitar o Acordo, os IBOs e os Clientes reconhecem que relatórios comerciais, identidade e informações de contato de Clientes, IBOs e Clientes ou IBOs potenciais (incluindo as disponíveis em chats em grupo), informações sobre a genealogia da EVO Global ou de um IBO, e quaisquer outras informações financeiras, técnicas ou de outro tipo que não sejam de conhecimento geral e/ou sejam de natureza sensível e circuladas pela EVO Global ou pertençam ao negócio da EVO Global, sejam escritas ou de outra forma, recebidas diretamente da EVO Global ou de outros IBOs, são informações confidenciais, proprietárias e segredos comerciais pertencentes à Evo Movement International S.A. de C.V.';

    //-------------------------//

$Politics_12_02 = '12.2 Obrigação de Confidencialidade';
$Politics_12_02_text = 'Os IBOs não devem usar as Informações Confidenciais e Segredos Comerciais da Evo Movement International S.A. de C.V. para qualquer propósito que não seja promover o negócio da EVO Global de um IBO. Um IBO nunca pode divulgar as Informações Confidenciais e Segredos Comerciais não públicos da Evo Movement International S.A. de C.V. a ninguém fora da EVO Global sem o consentimento por escrito da direção da EVO Global.';

    //-------------------------//

$Politics_12_03 = '12.3 Incumprimento e Recursos';
$Politics_12_03_text = 'Os IBOs reconhecem que as Informações Confidenciais e Segredos Comerciais não públicos da EVO Global são de tal caráter que as tornam únicas, e que a divulgação ou uso delas em violação da §12.1 e seguintes resultará em dano imediato e irreparável à EVO Global e aos negócios da EVO Global dos IBOs. Além de recuperar quaisquer danos, a EVO Global e seus IBOs terão direito a medidas injuntivas aceleradas contra qualquer IBO que viole esta disposição em qualquer ação para fazer cumprir seus direitos sob esta seção. A EVO Global pode buscar tal alívio injuntivo de forma acelerada sob as leis internacionais e mexicanas aplicáveis. A parte vencedora terá direito à adjudicação de honorários advocatícios, custos judiciais e despesas.';

    //-------------------------//

$Politics_12_04 = '12.4 Devolução de Materiais';
$Politics_12_04_text = 'Um IBO deve devolver imediatamente à EVO Global o original e todas as cópias de todas as Informações Confidenciais e Segredos Comerciais da EVO Global em posse dessa pessoa ao (1) encerrar este Acordo, ou (2) mediante solicitação da EVO Global.';

